def semver_sort(versions):
    def parse_version(v):
        # Split build metadata
        if '+' in v:
            version_part, build = v.split('+', 1)
        else:
            version_part = v
            build = ''

        # Split pre-release
        if '-' in version_part:
            core, prerelease = version_part.split('-', 1)
        else:
            core = version_part
            prerelease = None

        # Parse core version
        parts = core.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        if prerelease is not None:
            prerelease_identifiers = prerelease.split('.')
            # Convert to comparable format
            parsed_prerelease = []
            for identifier in prerelease_identifiers:
                if identifier.isdigit():
                    parsed_prerelease.append((0, int(identifier)))
                else:
                    parsed_prerelease.append((1, identifier))
        else:
            parsed_prerelease = None

        return (major, minor, patch, prerelease_identifiers if prerelease is not None else [], parsed_prerelease)

    def compare_key(item):
        v, idx = item
        major, minor, patch, prerelease_ids, parsed_prerelease = parse_version(v)

        # For sorting:
        # - Compare major, minor, patch numerically
        # - If no pre-release, it sorts after pre-release (use infinity)
        # - Pre-release versions sort by their identifiers
        if parsed_prerelease is None:
            # No pre-release: sort after any pre-release of same version
            return (major, minor, patch, (1,), idx)
        else:
            # Has pre-release: sort before no pre-release
            return (major, minor, patch, (0, tuple(parsed_prerelease)), idx)

    return sorted(enumerate(versions), key=compare_key)[len(versions)::-1][:-1][::-1]

